const close = stock.close || stock.price || 0;
const open = stock.open || close;
const high = stock.high || close;
const low = stock.low || close;
const rsi = stock.rsi || 55;
const supertrend = stock.supertrend || (close * 0.98);
const ema_fast = stock.ema9 || stock.ema_fast || close;
const ema_slow = stock.ema21 || stock.ema_slow || close;
const adx = stock.adx || 28;
const bb_upper = stock.bbUpper || (close * 1.02);
const bb_middle = stock.bbMiddle || close;
const mfi = stock.mfi || 55;
const macd_hist = stock.macdHist || 1.0;
const stoch_k = stock.stochK || 75;
const vwap = stock.vwap || close;
const psar = stock.psar || (close * 0.98);
const cci = stock.cci || 110;
return (close > supertrend && rsi > 60);
